tool_input.command:
awk -F, 'NR==1{print "id,ts,prediction,day"; next}{
  s=$1; gsub(/[-T:Z]/," ",s);
  ms=mktime(s)*1000;
  d=substr($1,1,10);
  print (NR-1)","ms","$2","d
}' data/prediction_log.csv > .tmp/pred_fg2.csv
head -3 .tmp/pred_fg2.csv; tail -1 .tmp/pred_fg2.csv

awk -F, 'BEGIN{off[1]=0;off[2]=31;off[3]=59}
NR==1{print "id,ts,prediction,day"; next}{
  split($1,a,"T"); split(a[1],dt,"-"); t=a[2]; gsub(/Z/,"",t); split(t,tm,":");
  y=dt[1]; mo=dt[2]+0; da=dt[3]+0;
  esec=(20454+off[mo]+(da-1))*86400 + tm[1]*3600 + tm[2]*60 + tm[3];
  print (NR-1)","(esec*1000)","$2","a[1]
}' data/prediction_log.csv > .tmp/pred_fg2.csv
head -3 .tmp/pred_fg2.csv; tail -2 .tmp/pred_fg2.csv; wc -l .tmp/pred_fg2.csv
